  const normalizeLanguage = value => String(value || "").trim().toLowerCase().replace("_", "-");

  function detectLanguage() {
    const candidates = [
      document.documentElement?.lang,
      document.documentElement?.getAttribute?.("xml:lang"),
      document.querySelector?.('meta[http-equiv="content-language" i]')?.content,
    ].map(normalizeLanguage).filter(Boolean);

    for (const candidate of candidates) {
      if (candidate === "en" || candidate.startsWith("en-")) return "en";
      if (candidate === "da" || candidate.startsWith("da-")) return "da";
    }

    const pathLanguage = String(location.pathname || "").match(/^\/([a-z]{2})(?:-[a-z]{2})?\//i)?.[1]?.toLowerCase();
    if (pathLanguage === "en" || pathLanguage === "da") return pathLanguage;

    const navigationText = Array.from(document.querySelectorAll?.("header, nav, .menu, .navigation") || [])
      .slice(0, 8)
      .map(node => String(node.textContent || ""))
      .join(" ");
    if (/\b(?:Overview|Players|Tactics|Training|Market|World|Help)\b/i.test(navigationText)) return "en";
    return "da";
  }

