(() => {
  "use strict";
  if (window.__VIRM_TRAINING_PLANNER_ROUTE_BOOTSTRAP_01267__) return;
  window.__VIRM_TRAINING_PLANNER_ROUTE_BOOTSTRAP_01267__ = true;

  const normalizePath = (value = window.location.pathname) => String(value || "/").replace(/\/+$/, "") || "/";
  const isPlannerPath = (value = window.location.pathname) => /^\/(?:[a-z]{2}(?:-[a-z]{2})?\/)?squads\/\d+\/training_exercises$/i.test(normalizePath(value));
  let previousPath = normalizePath();
  let reloading = false;

  const maybeReloadForPlanner = () => {
    const currentPath = normalizePath();
    const changed = currentPath !== previousPath;
    previousPath = currentPath;
    if (!changed || reloading || !isPlannerPath(currentPath)) return;
    if (document.getElementById("virm-extension-host")) return;
    reloading = true;
    window.location.reload();
  };

  window.addEventListener("popstate", maybeReloadForPlanner, true);
  window.addEventListener("hashchange", maybeReloadForPlanner, true);
  const routeObserver = new MutationObserver(maybeReloadForPlanner);
  const startObserver = () => {
    if (!document.documentElement) return;
    routeObserver.observe(document.documentElement, { childList: true, subtree: true });
  };
  if (document.documentElement) startObserver();
  else document.addEventListener("DOMContentLoaded", startObserver, { once: true });
})();


