  function uid(prefix) {
    if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
      return `${prefix}-${globalThis.crypto.randomUUID()}`;
    }
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  }

  function deepClone(value) {
    if (typeof structuredClone === "function") {
      return structuredClone(value);
    }
    return JSON.parse(JSON.stringify(value));
  }

  function normalizeText(value) {
    return String(value || "").replace(/\s+/g, " ").trim();
  }

  function clamp(value, minimum, maximum) {
    return Math.max(minimum, Math.min(maximum, value));
  }

  function todayISO(date = new Date()) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function dateOrdinal(isoDate) {
    const match = String(isoDate || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (!match) return null;
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    const value = Date.UTC(year, month - 1, day);
    const check = new Date(value);
    if (check.getUTCFullYear() !== year || check.getUTCMonth() !== month - 1 || check.getUTCDate() !== day) return null;
    return Math.floor(value / 86400000);
  }

  function shiftISODate(isoDate, dayDelta) {
    const ordinal = dateOrdinal(isoDate);
    if (ordinal === null) return todayISO();
    return new Date((ordinal + dayDelta) * 86400000).toISOString().slice(0, 10);
  }

  function dayIndexForDate(startDate, targetDate = todayISO()) {
    const start = dateOrdinal(startDate);
    const target = dateOrdinal(targetDate);
    return start === null || target === null ? null : target - start;
  }

  function bindNumberWheel(input, { minimum, maximum, step, decimals = 0, commit = false }) {
    input.addEventListener("wheel", (event) => {
      if (input.disabled) return;
      event.preventDefault();
      const current = Number(input.value) || minimum;
      const direction = event.deltaY < 0 ? 1 : -1;
      const next = clamp(current + direction * step, minimum, maximum);
      input.value = decimals > 0 ? next.toFixed(decimals) : String(Math.round(next));
      input.dispatchEvent(new Event("input", { bubbles: true }));
      if (commit) {
        input.dispatchEvent(new Event("change", { bubbles: true }));
      }
    }, { passive: false });
  }

