    const intensity = assistantCheckbox("Intensitetsforøgelse", assistant.allowIntensityBoost, (checked) => {
      assistant.allowIntensityBoost = checked;
      persistAssistantChange();
      renderEditor();
    });
    const timingButton = document.createElement("button");
    timingButton.type = "button";
