    globalCheckbox.addEventListener("change", e => { e.stopPropagation(); applyScope("global"); });
    backBtn.addEventListener("click", e => { e.stopPropagation(); popup.dataset.virmMenuView="main"; main.hidden=false; sub.hidden=true; });
    document.addEventListener("click", e => { if(control.isConnected && !control.contains(e.target)) close(); });
    document.addEventListener("keydown", e => { if(e.key==="Escape") close(); });
